def importar_tareas_anteriores(apps, schema_editor):
    TareaAnterior = apps.get_model('core', 'Tarea')
    Area = apps.get_model('organizacion', 'Area')
    Tarea = apps.get_model('organizacion', 'Tarea')
    estados = {
        'pendiente': 'pendiente', 'en_progreso': 'en_progreso',
        'completada': 'completada', 'cancelada': 'cancelada',
    }
    for anterior in TareaAnterior.objects.all().iterator():
        area, _ = Area.objects.get_or_create(
            usuario_id=anterior.usuario_id,
            nombre='Importadas',
            defaults={'descripcion': 'Tareas migradas desde el módulo anterior.', 'color': '#64748b'},
        )
        Tarea.objects.get_or_create(
            legacy_task_id=anterior.pk,
            defaults={
                'usuario_id': anterior.usuario_id,
                'area_id': area.pk,
                'titulo': anterior.titulo,
                'descripcion': anterior.descripcion,
                'estado': estados.get(anterior.estado, 'pendiente'),
                'prioridad': anterior.prioridad,
                'fecha_planificada': anterior.fecha,
            },
        )


def retirar_importacion(apps, schema_editor):
    apps.get_model('organizacion', 'Tarea').objects.filter(legacy_task_id__isnull=False).delete()


